function LimitedTimeSaleMainDialog:__init()
    self.parameters = nil
    self.requestSuccess = false
    self._behaviourAction = nil
    self.isBuying = false
end

function LimitedTimeSaleMainDialog:__delete()
    self.parameters = nil
    self.controller = nil
