    self._behaviourAction = nil
    self.isBuying = false
end

function LimitedTimeSaleMainDialog:Awake()
    if isNull(self._behaviourAction) then
        self._behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
        self._behaviourAction.UpdateAction = function()
            self:OnUpdate()
        end
    end
    self.parameters = self.controller.Argument.parameters
    CfUtils.SetActive(self.BtnRoleNameNode, false)
    ---@type CardProgressionControllerRole
    self._controllerEnv = CardProgressionUtils.GetRoleControllerEnv()
    self:InitChestGo()
end

function LimitedTimeSaleMainDialog:InitChestGo()
    local allVo = CfUtils.GetCf(AutoIds.IdSetting6075, "TimeLimitedSaleChestVo", true)
    if #allVo > countFlag  then
        return
    end

    self.chestGo = {}
    for i = 1, #allVo do
        ResourceModule.LoadGameObjectAsync("Prefabs/LimitedTimeSale/LimitedChestPointNode.prefab", function(go)
            go.name = "LimitedChestPointNode" .. checkString(i)
            self.chestGo[i] = go
        end, true, self.LoopGridChest1, true, false)
    end
end

function LimitedTimeSaleMainDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:InitHandler()
        self._roleId = LimitedTimeSaleMgr:LoadRoleId()
        self:RefreshRoleInfo(self._roleId)
        if LimitedTimeSaleMgr:IsFirstOpenDialog() then
            self:InitFirstShow()
        else
            self.requestSuccess = false
            self:InitData()
        end

        while not self.requestSuccess do
            coroutine.yield()
        end
        Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = false })
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
        cs_coroutine.yield_return(self._controllerEnv:LoadRoleUIShow(self._activityVo.showRoleId ,CardProgressionConstants.CameraState.ShowRoleOnUI,nil, self._activityVo.lensRotation, self._activityVo.roleIdMove, self._activityVo.roleIdRotation))
    end))
    return coWait
end

function LimitedTimeSaleMainDialog:OnFocus(focus)
    if focus then
        ---@type ServerDifferenceMgr
        local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
        ServerDifferenceMgr:RefreshNavigatorGoods(true)
    end
end

function LimitedTimeSaleMainDialog:OnShow()
    CfUtils.PlayAnimation(self.Root, "LimitedTimeSaleDialog_Entry")
end

function LimitedTimeSaleMainDialog:OnHide()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.ResetNavigatorCustomBackAction()
        cs_coroutine.yield_return(function()
            local effectBg = self.controller.gameObject:GetComponent(typeof(UIEffectCapturedImage))
            if effectBg then
                effectBg:Capture()
            end
        end)
    end))
    return coWait
end

function LimitedTimeSaleMainDialog:OnUpdate()
    if checkBool(self.refreshTime) then
        if self.cardStarGiftDojo.remainTime <= 0 then

            self.refreshTime = false
            CfUtils.StartCoroutineWithBlocker(function()
                CfUtils.PlayAnimation(self.Root, "LimitedTimeSaleDialog_Out")
                cs_coroutine.yield_return(WaitForSeconds(1))
                UIModule.BackDialog()
            end)
        end
        CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS4(self.cardStarGiftDojo.remainTime,"00f6E7"))
    end
end

function LimitedTimeSaleMainDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self._behaviourAction) then
            self._behaviourAction.UpdateAction = nil
        end

        if self.cardStarGiftDojo then
            self.cardStarGiftDojo:RemoveTimer()
            self.cardStarGiftDojo = nil
        end

        if self._eventCarStarGift then
            Events.RemoveListener("EVENT_LimitedTimeSaleMgr_CarStarGift_Requested", self._eventCarStarGift)
            self._eventCarStarGift = nil
        end

        if self.__EventSdkEvent then
            Events.RemoveListener(Constants.EventNames.EVENT_SDK, self.__EventSdkEvent)
            self.__EventSdkEvent = nil
        end
        self._controllerEnv:CleanUiRole()
        self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

