--region handler
function LimitedTimeSaleMainDialog:OnEventTriggerCarStarGiftHandler()
    ---@type PlayerComponent
    local PlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    ---@type CardStarGiftDojo
    self.cardStarGiftDojo = clone(PlayerComponent:GetCardStarGiftDojo())

    self._activityId = self.cardStarGiftDojo.id
    self._buyId = self.cardStarGiftDojo.buyId
    self._gifts = self.cardStarGiftDojo.gifts
    self.cardStarGiftDojo:StartTimeDown()

    if isNull(self._activityVo) then
        self._activityVo = LimitedTimeSaleMgr:LoadActivityById(self._activityId)
    end

    if isNull(self._chestVoList) then
        self._chestVoList = LimitedTimeSaleMgr:LoadAllChestVo()
    end
    self.requestSuccess = true
    self:RefreshUI()
end

function LimitedTimeSaleMainDialog:OnClickBtnCloseHandler()
    self:PanelClose()
end

---@param payInfo table
function LimitedTimeSaleMainDialog:OnPayMoneyHandler(payInfo)
    if payInfo then
        SDKService:GetInstance():PayMoney({
            productId = payInfo.productId,
            channelProductId = payInfo.channelProductId,
            productDesc = localize("限时礼包"),
            payAmount = payInfo.price,
            data = payInfo
        })
    end
end

--支付成功
function LimitedTimeSaleMainDialog:OnEventSdkEvent(parameters)
    --- sdk pay succeed
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        self:InitData()
    end
end

