function LimitedTimeSaleMainDialog:PanelClose()
    if self.isBuying then return end
    CfUtils.StartCoroutineWithBlocker(function()
        CfUtils.PlayAnimation(self.Root, "LimitedTimeSaleDialog_Out")
        local isBuyAll = true
        for k, v in pairs(self.cardStarGiftDojo.gifts) do
            if self.cardStarGiftDojo.buyId < tonumber(k) then
                isBuyAll = false
                break
            end
        end
        cs_coroutine.yield_return(WaitForSeconds(0.15))
        cs_coroutine.yield_return(UIModule.BackDialog())

        if not isBuyAll then
            Events.Broadcast(Constants.EventNames.START_SHOW_BOOM_MOVE,Constants.UIHomeViewBtnType.LimitedTimeSale)
        end

        --Events.Broadcast(Constants.EventNames.ActivityTimeLimitedDialogClose, self.Root.transform.position)
    end)
end

function LimitedTimeSaleMainDialog:RefreshRoleInfo(roleId)
    local roleData = CardConfMgr:GetInstance():GetCardByRefId(roleId)
    if isNull(roleData) then
        return
    end

    CfUtils.SetActive(self.BtnRoleNameNode.gameObject, true)
    local roleNameNode = CfUtils.GetLuaScr(self.BtnRoleNameNode.gameObject, "Game.UI.Common.CommonBtnRoleNameNode")
    if roleNameNode then
        roleNameNode:RefreshSelf(roleId, nil, function()
            xTry(function()
                local GachaponUtils = import('Game.Gachapon.GachaponUtils')
                GachaponUtils.OpenDetail(roleId, { { id = Constants.UITypeIds.LimitedTimeSaleDialog } })
            end)
        end, false)
    end
end

function LimitedTimeSaleMainDialog:RefreshTime()
