---RefreshChest 刷新宝箱UI
function LimitedTimeSaleMainDialog:RefreshChest()
    local chestCount = #self._chestVoList

    if chestCount > countFlag then

        CfUtils.SetActive(self.LoopGridChest1, false)
        CfUtils.SetActive(self.LoopGridChest2, true)

        self.LoopGridChest2:InitGridView(chestCount, Bind(self, self.OnRefreshItem))
    else
        CfUtils.SetActive(self.LoopGridChest1, true)
        CfUtils.SetActive(self.LoopGridChest2, false)

        for i, chest in ipairs(self._chestVoList) do
            local chestGo = self.chestGo[i]
            if chestGo then
                self:RefreshChestNode(chest, i)
            end
        end
    end
end

function LimitedTimeSaleMainDialog:RefreshChestNode(chest, index)
    chest.isLock = (self._buyId == 0 or self._buyId < chest.id)
    chest.isLast = (index >= #self._chestVoList)
    chest.isCurBuy = false

    if self._buyId > 0 and chest.id == self._buyId then
        if index + 1 <= #self._chestVoList then
            self.curBuyId = self._chestVoList[index + 1].id
        else
            self.curBuyId = nil
            self:RefreshTitleState(chest)
            self:RefreshGoods(chest)
            self:RefreshBtnCost(chest)
        end
    end

    if (self._buyId == 0 and index == 1) or (self.curBuyId and self.curBuyId == chest.id) then
        chest.isCurBuy = true
        self:RefreshTitleState(chest)
        self:RefreshGoods(chest)
        self:RefreshBtnCost(chest)
    end

    local chestGo = self.chestGo[index]
    if chestGo then
        ---@type ChestPointNodeBehavior
        local scr = CfUtils.GetLuaScr(chestGo, "Game.UI.LimitedTimeSale.ChestPointNodeBehavior")
        local isSelect = false
        if isNull(self._curSelectChestId) and chest.isCurBuy then
            isSelect = true
        else
            isSelect = self._curSelectChestId == chest.id
        end

        scr:Refresh({
            isLock = checkBool(chest.isLock),
            isSelected = isSelect,
            isCurBuy = chest.isCurBuy,
            isLast = chest.isLast
        })

        KTool.GetOrAddComponent(chestGo.transform:Find("BtnChest").gameObject, typeof(CS.Engine.UI.UIEventProxy)).onPointerClick = Bind(self, function()
            self._curSelectChestId = chest.id
            if #self._chestVoList > countFlag then
                GameUtils.ReloadData(self.LoopGridChest2, #self._chestVoList)
            else
                self:RefreshChest()
            end

            self:RefreshTitleState(chest)
            self:RefreshGoods(chest)
            self:RefreshBtnCost(chest)
        end)
    end
end

function LimitedTimeSaleMainDialog:OnRefreshItem(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("LimitedChestPointNode")
    local luaIndex = index + 1
    local chest = self._chestVoList[luaIndex]
    chest.go = cell
    self:RefreshChestNode(chest, luaIndex)

    return cell
end

---@param chest TimeLimitedSaleChestVo
function LimitedTimeSaleMainDialog:RefreshTitleState(chest)
    CfUtils.FillText(self.Text1, chest.text)
    CfUtils.FillText(self.TxtNumber, checkString(chest.value))
end

---RefreshGoods 刷新宝箱中的商品
---@param chest TimeLimitedSaleChestVo
function LimitedTimeSaleMainDialog:RefreshGoods(chest)
    local goodsId = chest.goodsId
    local firstGoods = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId[1])
    ---@type GoodNodeMB
    local scr = CfUtils.GetLuaScr(self.GoodNodeBig, "Game.Behaviours.GoodNodeMB")
    scr:Reload({
        goodsId = firstGoods.id,
        text = string.format("x%d", chest.goodsNum[1]),
        isShowNo = true
    })
    scr:SetSanXingGainShow(not chest.isLock)

    scr:SetClickButtonAction(function(goodsId)
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        if isTable(goodsVo) then
            GameUtils.ShowCommonTipsBoard(self.GoodNodeBig.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
        end
    end)

    local goodsList = {}
    for i = 2, #goodsId do
        local goods = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId[i])
        goods.goodsNum = chest.goodsNum[i]
        table.insert(goodsList, goods)
    end
    ---@type CommonGoodsList
    local goodsEnv = CfUtils.GetLuaScr(self.CommonGoodsListLight, "Game.Behaviours.CommonGoodsListLight")
    goodsEnv:FreshBaseUI(goodsList, false, not chest.isLock)
end

---@param chest TimeLimitedSaleChestVo
function LimitedTimeSaleMainDialog:RefreshBtnCost(chest)
    local isLock = chest.isLock
    local isCurBuy = chest.isCurBuy
    if not isLock then
        KTool.SetActive(self.BtnCost, false)
        KTool.SetActive(self.FontStyleButton, true)
        CfUtils.FillText(self.Text, localize("已售光"))
        return
    end

    if not isCurBuy then
        KTool.SetActive(self.BtnCost, false)
        KTool.SetActive(self.FontStyleButton, true)
        CfUtils.FillText(self.Text, localize("未解锁"))
        return
    end

    local gift = self._gifts[checkString(chest.id)]
    if isNull(gift.prices) then
        gift.prices = {}
    end
    KTool.SetActive(self.BtnCost, true)
    KTool.SetActive(self.FontStyleButton, false)
    CfUtils.SetActive(self.TxtNum.transform.parent:Find("Txtbuy"), table.count(gift.prices) == 0)
    if table.count(gift.prices) > 0 then
        ---一级道具购买
        CfUtils.SetActive(self.TxtNum.transform.parent:Find("ImgIcon"), true)
        local goodsId = checkNumber(table.takeFirst(table.keys(gift.prices)))
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        CfUtils.FillImage(self.TxtNum.transform.parent:Find("ImgIcon"), vo.photoPath)
        local dojo = gift.prices[tostring(goodsId)]
        local price = checkNumber(dojo.current)
        CfUtils.FillText(self.TxtNum, price)
        local productId = checkNumber(gift.productId)
        KTool.GetOrAddComponent(self.BtnCost.gameObject, typeof(CS.Engine.UI.UIEventProxy)).onPointerClick = function()
            ---调用道具消耗的逻辑处理
            ---@type ServerDifferenceMgr
            local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
            ServerDifferenceMgr:WrapPrimaryCurrencyBuy({
                currency = goodsId,
                current = price,
            }, function(isSuccess)
                isSuccess = checkBool(isSuccess)
                if not isSuccess then
                    return
                end
                self.isBuying = true
                ----请求兑换的逻辑
                GameUtils.Request(Interfaces.MallStarGiftBuy, {
                    productId = productId,
                    num = 1,
                    currency = goodsId,
                }, function(request, resp)
                    if checkNumber(resp.errCode) == 0 then
                        xTry(function()
                            local reward = checkTable(resp.data.rewards)
                            GoodsUtils.DrawRewards({ {
                                                         goodsId = goodsId,
                                                         num = -price
                                                     } })
                            if #reward > 0 then
                                GoodsUtils.DrawRewards(reward)
                                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = reward } })
                            end
                            self:InitData()
                            self.isBuying = false
                        end, function()
                            self.isBuying = false
                        end)
                    else
                        self.isBuying = false
                    end
                end)
            end)
        end
    else
        local channelProductId = gift.channelProductId
        CfUtils.FillText(self.TxtNum, CfUtils.GetDisplayPrice(gift.price, channelProductId))
        local payInfo = {
            productId = gift.productId,
            channelProductId = gift.channelProductId,
            price = gift.price,
        }

        KTool.GetOrAddComponent(self.BtnCost.gameObject, typeof(CS.Engine.UI.UIEventProxy)).onPointerClick = function()
            self:OnPayMoneyHandler(payInfo)
        end
    end
end
